<?php require __DIR__.'/bootstrap.php';require_login();$msg='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$st=$pdo->prepare('SELECT password_hash FROM users WHERE id=?');$st->execute([$_SESSION['user']['id']]);$hash=$st->fetchColumn();if(!password_verify($_POST['current']??'',$hash))$error='Senha atual incorreta.';elseif(strlen($_POST['password']??'')<12)$error='A nova senha deve ter ao menos 12 caracteres.';elseif($_POST['password']!==($_POST['confirm']??''))$error='A confirmação não confere.';else{$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($_POST['password'],PASSWORD_DEFAULT),$_SESSION['user']['id']]);$msg='Senha alterada com sucesso.';}}?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Minha conta | Newsiga</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="top"><a class="brand" href="<?=url('dashboard.php')?>">newsiga</a><nav><a href="<?=url('dashboard.php')?>">Painel</a><a href="<?=url('logout.php')?>">Sair</a></nav></header><main class="container" style="max-width:620px"><p class="kicker">MINHA CONTA</p><h1>Alterar senha</h1><?php if($msg):?><p class="success"><?=e($msg)?></p><?php endif;?><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><section class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Senha atual<input name="current" type="password" required></label><label>Nova senha<input name="password" type="password" minlength="12" required></label><label>Confirmar nova senha<input name="confirm" type="password" minlength="12" required></label><button class="button">Alterar senha</button></form></section></main></body></html>
